CREATE OR REPLACE FUNCTION calculate_avg_inquiry_rate(listing_tier VARCHAR)
RETURNS NUMERIC AS $$
BEGIN
  RETURN (
    SELECT COALESCE(ROUND(AVG(s.inquiries_received::NUMERIC / s.views_received), 4), 0.0000)
    FROM saved_searches s
    JOIN listings l ON s.listing_id = l.listing_id
    WHERE l.tier = listing_tier
      AND s.views_received > 0
  );
END;
$$ LANGUAGE plpgsql;

SELECT calculate_avg_inquiry_rate('premium') AS result;
